
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_regtpss_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_regtpss", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.438110815570897e-02, -6.334255484859871e-02, -6.185369591760909e-02, -5.972247741482342e-02, -5.667891975032370e-02, -5.235051163423078e-02, -4.624864710792518e-02, -3.783697498459364e-02, -2.698594187085581e-02, -1.570909984166263e-02, -1.147007138473980e-02, -3.856022818051355e-02, -4.641615916622360e-02, -3.271009176795035e-02, -1.708256377074659e-02, -4.547442470835074e-03, -3.271539227352224e-04, -4.190141978334790e-06, -5.485259278460936e-09, -2.342889909071260e-13]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


